             OR session_user IS DISTINCT FROM 'legacy_note_adapter_runner' THEN
            RAISE EXCEPTION 'LEGACY_MIGRATION_EVENT_APPEND_ONLY';
          END IF;
          BEGIN m:=pg_catalog.current_setting('app.legacy_transition_guard',true)::jsonb;
